import sys

def solve(records):
    result = []
    for record in records:
        timeout = record.get('timeout')
        enabled = record.get('enabled')
        if timeout is None:
            timeout = 30
        if enabled is None:
            enabled = True
        if type(timeout) is not int or not 0 <= timeout <= 120 or type(enabled) is not bool:
            status = 'invalid'
        elif not enabled:
            status = 'disabled'
        elif timeout == 0:
            status = 'poll'
        else:
            status = 'wait'
        result.append(status)
    return result

