import json
import re
import sys

def parse_count(value):
    if not isinstance(value, str) or re.fullmatch(r'[+-]?[0-9]+', value.strip()) is None:
        raise ValueError('invalid integer text')
    count = int(value.strip())
    if count < 0:
        raise ValueError('negative count')
    return count

def solve(payload):
    accepted = []
    rejected = []
    for position, value in enumerate(payload['values']):
        try:
            count = parse_count(value)
        except ValueError:
            if payload['mode'] == 'strict':
                return {'error_index': position}
            rejected.append(position)
        else:
            accepted.append(count)
    if payload['mode'] == 'strict':
        return {'accepted': accepted}
    return {'accepted': accepted, 'rejected': rejected}

if __name__ == '__main__':
    print(json.dumps(solve(json.load(sys.stdin)), separators=(',', ':'), sort_keys=True))

import json
import sys

def unique_keys(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate key')
        result[key] = value
    return result

def solve(text):
    try:
        records = json.loads(text, object_pairs_hook=unique_keys)
    except ValueError:
        return 'INVALID_JSON'
    if not isinstance(records, list):
        return 'INVALID_SCHEMA'
    total = 0
    for record in records:
        if not isinstance(record, dict) or set(record) != {'name', 'score'}:
            return 'INVALID_SCHEMA'
        if not isinstance(record['name'], str) or not record['name'].strip():
            return 'INVALID_SCHEMA'
        score = record['score']
        if type(score) is not int or not 0 <= score <= 100:
            return 'INVALID_SCHEMA'
        total += score
    return {'count': len(records), 'total': total}

if __name__ == '__main__':
    result = solve(sys.stdin.read())
    print(result if isinstance(result, str) else json.dumps(result, separators=(',', ':'), sort_keys=True))

