import json
import sys

class Ledger:
    def __init__(self):
        self.balance = 0
        self.history = []

    def apply(self, action, amount):
        if type(amount) is not int or amount <= 0 or action not in {'deposit', 'withdraw'}:
            raise ValueError('invalid operation')
        if action == 'withdraw' and amount > self.balance:
            raise ValueError('insufficient balance')
        change = amount if action == 'deposit' else -amount
        self.balance += change
        self.history.append(change)

def solve(payload):
    ledgers = {owner: Ledger() for owner in payload['owners']}
    rejected = []
    for position, (owner, action, amount) in enumerate(payload['commands']):
        try:
            ledgers[owner].apply(action, amount)
        except ValueError:
            rejected.append(position)
    return {'balances': {owner: ledger.balance for owner, ledger in ledgers.items()}, 'histories': {owner: ledger.history for owner, ledger in ledgers.items()}, 'rejected': rejected}

if __name__ == '__main__':
    print(json.dumps(solve(json.load(sys.stdin)), separators=(',', ':'), sort_keys=True))

