import json
import sys

def solve(payload):
    if not isinstance(payload, dict) or set(payload) != {'records'} or not isinstance(payload['records'], list):
        return {'error': 'invalid'}
    for record in payload['records']:
        if not isinstance(record, dict) or set(record) != {'name', 'score'}:
            return {'error': 'invalid'}
        if not isinstance(record['name'], str) or not record['name'].strip():
            return {'error': 'invalid'}
        if type(record['score']) is not int or not 0 <= record['score'] <= 100:
            return {'error': 'invalid'}
    groups = {}
    for record in payload['records']:
        name = record['name'].strip()
        key = name.casefold()
        if key not in groups:
            groups[key] = {'name': name, 'attempts': 0, 'total': 0}
        groups[key]['attempts'] += 1
        groups[key]['total'] += record['score']
    ordered_keys = sorted(groups, key=lambda key: (-groups[key]['total'], key))
    return [groups[key] for key in ordered_keys]

def main():
    try:
        payload = json.load(sys.stdin)
    except ValueError:
        result = {'error': 'invalid'}
    else:
        result = solve(payload)
    print(json.dumps(result, ensure_ascii=False, separators=(',', ':'), sort_keys=True))

if __name__ == '__main__':
    main()
